// DMs with purchase intent since the last poll. Emits ONE item: { watermark, leads[] }.
// DMs only — likes, comments, follows and mentions are ignored.
const raw = $input.first().json;
let payload = (raw && raw.content && raw.content[0]) ? raw.content[0].text : raw;
if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch (e) { payload = null; } }
const events = (payload && Array.isArray(payload.events)) ? payload.events : [];
const apiTotal = (payload && typeof payload.total === 'number') ? payload.total : events.length;
const organization_id = (payload && payload.organizationId) ? String(payload.organizationId) : '';

const prevTs = Number(($('Retrieve Watermark Data').first().json || {}).value || 0) || 0;

const DM_TYPES = ['message', 'dm', 'direct_message'];

// word-boundary matcher — stops "order" matching "border", "cost" matching "costume"
function boundary(kw) {
  const esc = String(kw).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  try { return new RegExp('(?<![\\p{L}\\p{N}])' + esc + '(?![\\p{L}\\p{N}])', 'iu'); }
  catch (e) { return new RegExp(esc, 'i'); }
}
const INTENT = ['buy','buying','purchase','purchasing','order','preorder','pre-order','price','pricing',
  'cost','checkout','payment','how much','where can i buy','where can i get','in stock','restock',
  'sold out','discount','promo code','sign up','subscribe','upgrade','interested','want one','get one'];
const intentRes = INTENT.map(boundary);

function igThreadId(messageId) {
  if (!messageId) return null;
  const s = String(messageId);
  const cands = s.indexOf('ZA') === -1 ? [s] : [s, s.replace(/ZA/g, 'Z')];
  for (const c of cands) for (let p = 0; p < 4; p++) {
    let dec = '';
    try { dec = Buffer.from(c + '='.repeat(p), 'base64').toString('utf8'); } catch (e) { continue; }
    const m = dec.match(/^ig_dm_item:\d+:IGMessageID:\d+:(\d+):\d+/);
    if (m) return m[1];
  }
  return null;
}
function replyUrl(ev) {
  const inbox = organization_id ? 'https://copilot.fanbase.gg/o/' + organization_id + '/inbox' : '';
  const p = String(ev.platform || '').toLowerCase();
  const meta = ev.metadata || {};
  if (p === 'instagram') {
    const tid = igThreadId(meta.messageId);
    if (tid) return 'https://www.instagram.com/direct/t/' + tid + '/';
  }
  return inbox;
}
const secs = (ev) => {
  const t = new Date((ev.metadata && ev.metadata.timestamp) || ev.createdAt || '').getTime();
  return Number.isFinite(t) ? Math.floor(t / 1000) : 0;
};

let newest = prevTs;
const leads = [];
const seen = new Set();

for (const ev of events.slice().sort((a, b) => secs(b) - secs(a))) {   // newest first
  const ts = secs(ev);
  if (ts > newest) newest = ts;
  if (ts && ts <= prevTs) continue;                                    // already handled
  if (DM_TYPES.indexOf(String(ev.type || '').toLowerCase()) === -1) continue;   // DMs only

  const text = (ev.metadata && ev.metadata.text) ? String(ev.metadata.text) : '';
  if (!intentRes.some(re => re.test(text))) continue;

  const fanId = (ev.fan && ev.fan.id) ? String(ev.fan.id) : '';
  if (!fanId || seen.has(fanId)) continue;                             // one lead per fan per poll
  seen.add(fanId);

  leads.push({
    fan_id: fanId,
    fan_name: (ev.fan && ev.fan.name) || '',
    platform: ev.platform || '',
    intent_text: text.slice(0, 500),
    intent_at: (ev.metadata && ev.metadata.timestamp) || ev.createdAt || '',
    reply_url: replyUrl(ev),
  });
}

if (!newest) newest = Math.floor(Date.now() / 1000);
return [{ json: { watermark: String(newest), leads, lead_count: leads.length,
                  scanned: events.length, api_truncated: apiTotal > events.length } }];

// Joins each intent lead to its CRM record to get the handle, then emits ONE ITEM PER LEAD.
// fan.id (query_activity) == clusterId (list_crm) — verified against live data.
// list_crm caps at 100 rows per page and page 1 is all high-engagement twitter fans, so the
// Instagram fans who actually DM only appear on later pages — hence the merged page inputs.
const leads = ($('Identify Intent in DMs').first().json.leads) || [];
if (!leads.length) return [];

const fans = [];
let crmTotal = 0;
for (const item of $input.all()) {
  let p = (item.json && item.json.content && item.json.content[0]) ? item.json.content[0].text : item.json;
  if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { continue; } }
  if (!p) continue;
  if (typeof p.total === 'number') crmTotal = Math.max(crmTotal, p.total);
  for (const f of (p.fans || [])) fans.push(f);
}
const byId = {};
for (const f of fans) if (f && f.clusterId) byId[String(f.clusterId)] = f;

function profileUrl(platform, u) {
  if (!u) return '';
  const p = String(platform || '').toLowerCase();
  if (p === 'instagram') return 'https://www.instagram.com/' + u;
  if (p === 'twitter' || p === 'x') return 'https://x.com/' + u;
  if (p === 'tiktok') return 'https://www.tiktok.com/@' + u;
  return '';
}

return leads.map(lead => {
  const fan = byId[String(lead.fan_id)] || null;
  const profile = (fan && fan.profile) || {};
  return { json: Object.assign({}, lead, {
    handle: String(profile.username || ''),
    profile_url: profileUrl(lead.platform, profile.username),
    crm_truncated: crmTotal > fans.length,
  }) };
});

// Merges each Apify profile with its lead and produces ONE ROW PER LEAD.
// The Apify node ("Run an Actor and get dataset") emits dataset items FLAT — there is no MCP
// content[0].text envelope — and it emits NOTHING for a run that returns 0 items (bad/renamed
// handle), so rows are driven off the leads and matched to profiles by username, never by
// position. pairedItem (set by the Apify node to the input item index) is the fallback.
const leads = $('Resolve Social Handles').all().map(i => i.json);
const results = $input.all();

function unwrap(item) {
  const raw = (item && item.json) || {};
  if (Array.isArray(raw.content)) {                 // MCP shape, if that node is ever swapped back in
    for (const blk of raw.content) {
      let o = blk && blk.text;
      if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { continue; } }
      if (o && Array.isArray(o.items) && o.items.length) return o.items[0];
      if (Array.isArray(o) && o.length && o[0] && o[0].username) return o[0];
      if (o && (o.username || o.biography)) return o;
    }
    return null;
  }
  return (raw.username || raw.biography) ? raw : null;   // flat dataset item
}

const norm = (u) => String(u || '').trim().replace(/^@/, '').toLowerCase();
const slot = (item, i) => {
  const p = item && item.pairedItem;
  if (typeof p === 'number') return p;
  if (p && typeof p === 'object' && typeof p.item === 'number') return p.item;
  if (Array.isArray(p) && p.length && typeof p[0].item === 'number') return p[0].item;
  return i;
};

const byHandle = {}, byIndex = {}, errByIndex = {};
results.forEach((item, i) => {
  const idx = slot(item, i);
  const profile = unwrap(item);
  if (!profile) {
    const err = item && item.json && item.json.error;
    if (err && errByIndex[idx] === undefined) errByIndex[idx] = String(err.message || err);
    return;
  }
  const key = norm(profile.username);
  if (key && byHandle[key] === undefined) byHandle[key] = profile;
  if (byIndex[idx] === undefined) byIndex[idx] = profile;
});

const EMAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
function emailOf(profile, bio) {
  if (!profile) return '';
  // Instagram only exposes a contact email on some business accounts, so the bio is the main source.
  for (const v of [profile.businessEmail, profile.publicEmail, profile.email]) {
    const m = String(v || '').match(EMAIL);
    if (m) return m[0];
  }
  const inBio = String(bio || '').match(EMAIL);
  if (inBio) return inBio[0];
  for (const l of (Array.isArray(profile.externalUrls) ? profile.externalUrls : [])) {
    const u = String((l && l.url) || '');
    if (/^mailto:/i.test(u)) {
      const m = u.slice(7).match(EMAIL);
      if (m) return m[0];
    }
  }
  return '';
}

return leads.map((lead, i) => {
  const profile = byHandle[norm(lead.handle)] || byIndex[i] || null;
  const bio = profile ? String(profile.biography || '') : '';

  let note = '';
  if (!lead.handle) note = 'no handle in CRM' + (lead.crm_truncated ? ' (CRM paging incomplete)' : '');
  else if (!profile) note = errByIndex[i] ? 'scrape failed: ' + errByIndex[i] : 'scrape returned nothing';
  else if (profile.private) note = 'private account';

  return { json: {
    captured_at: new Date().toISOString(),
    fan_name: lead.fan_name || (profile ? profile.fullName : '') || '',
    handle: lead.handle || (profile ? String(profile.username || '') : ''),
    profile_url: lead.profile_url || (profile ? String(profile.url || '') : ''),
    platform: lead.platform || '',
    email: emailOf(profile, bio),
    link_in_bio: profile ? String(profile.externalUrl || '') : '',
    followers: profile && typeof profile.followersCount === 'number' ? profile.followersCount : '',
    posts: profile && typeof profile.postsCount === 'number' ? profile.postsCount : '',
    is_business: profile ? !!profile.isBusinessAccount : '',
    bio: bio.replace(/\s+/g, ' ').slice(0, 300),
    intent_text: lead.intent_text || '',
    intent_at: lead.intent_at || '',
    reply_url: lead.reply_url || '',
    fan_id: lead.fan_id || '',
    status: note ? 'captured (' + note + ')' : 'captured',
  } };
});
